from scipy.optimize import least_squares
def res(q, which):
    cols=[]
    for w in which:
        if w=='A': cols.append(T**q[0]*eps**q[1])
        if w=='B': cols.append(np.exp(-q[2]/T)*eps**q[3])
        if w=='C': cols.append(np.exp(-q[4]*eps)*T**q[5])
        if w=='D': cols.append(T**q[6]*np.log(eps))
        if w=='E': cols.append(np.exp(-q[7]/T)*np.exp(q[8]*eps))
        if w=='F': cols.append(T**q[9]*eps)
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,sigma,rcond=None)
    return sigma-X@c
